select.where:
bw_inventory_batch.is_deleted = 0 and bw_cargo.is_deleted = 0 and bw_inventory.is_deleted = 0 and bw_inventory.available_quantity != 0 and bw_cargo_position.is_deleted = 0 and bw_cargo_position.enable = 1
and bw_inventory.inventory_batch_id = #{inventoryBatchId}
and bw_inventory.position_id = #{positionId}
order by bw_inventory.id desc

mapper.select:
select bw_inventory.id, bw_cargo.cargo_name, bw_inventory.inventory_batch_id, bw_inventory_batch.batch_no as inventory_batch_no, bw_inventory.no as inventory_no, bw_inventory.available_quantity + bw_inventory.reserve_quantity as quantity, bw_inventory.unit_id, bw_inventory.position_id, concat((select group_concat(bw_storage.name separator '-') from bw_storage where find_in_set(bw_storage.id, bw_cargo_position.id_path)), '-', bw_cargo_position.position) as position, bw_inventory_batch.expired_date from bw_inventory left join bw_inventory_batch on bw_inventory.inventory_batch_id = bw_inventory_batch.id left join bw_cargo_position on bw_inventory.position_id = bw_cargo_position.id left join bw_cargo on bw_inventory.cargo_id = bw_cargo.id where bw_inventory.is_deleted = 0 and bw_inventory_batch.is_deleted = 0 and bw_inventory_batch.available = 1 and bw_cargo_position.is_deleted = 0 and bw_cargo.is_deleted = 0 and bw_cargo_position.enable = 1 and (bw_inventory.available_quantity + bw_inventory.reserve_quantity) > 0
and bw_inventory.cargo_id = #{cargoId}
and bw_inventory.inventory_batch_id = #{inventoryBatchId}
order by cast(bw_inventory.no as signed)
